export const WORLD = Object.freeze({
  seed: 42,
  chunkSize: 64,
  tileSize: 16,
  sourceTileSize: 32,
  overmapChunks: 6400,
  loadRadius: 2,
  unloadPadding: 1
});

export const LAYERS = Object.freeze({
  bedrock: 0,
  substrate: 1,
  terrain: 2,
  surface: 3,
  objects: 4,
  structures: 5,
  entities: 6,
  lighting: 7
});

import { WORLD } from './constants.js';

export function hash(n) {
  n = (n ^ 61) ^ (n >>> 16);
  n = Math.imul(n, 9);
  n = n ^ (n >>> 4);
  n = Math.imul(n, 0x27d4eb2d);
  n = n ^ (n >>> 15);
  return (n >>> 0) / 4294967295;
}

export function rand2(x, y, salt = 0, seed = WORLD.seed) {
  return hash(Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(seed + salt, 1442695041));
}

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function smoothNoise(x, y, scale, salt, seed = WORLD.seed) {
  const fx = x / scale;
  const fy = y / scale;
  const x0 = Math.floor(fx);
  const y0 = Math.floor(fy);
  const tx = fx - x0;
  const ty = fy - y0;
  const sx = tx * tx * (3 - 2 * tx);
  const sy = ty * ty * (3 - 2 * ty);
  const a = rand2(x0, y0, salt, seed);
  const b = rand2(x0 + 1, y0, salt, seed);
  const c = rand2(x0, y0 + 1, salt, seed);
  const d = rand2(x0 + 1, y0 + 1, salt, seed);
  return lerp(lerp(a, b, sx), lerp(c, d, sx), sy);
}

export function fbm(x, y, salt, seed = WORLD.seed) {
  let value = 0;
  let amplitude = 0.5;
  let scale = 180;
  for (let octave = 0; octave < 5; octave++) {
    value += smoothNoise(x, y, scale, salt + octave * 31, seed) * amplitude;
    scale *= 0.48;
    amplitude *= 0.5;
  }
  return value;
}

import { fbm } from '../core/random.js';

export const BIOMES = Object.freeze({
  ocean: { material: 'ocean_water', color: '#1c5d8f', walkable: false, movementCost: Infinity },
  beach: { material: 'golden_sand', color: '#d8bd75', walkable: true, movementCost: 1.15 },
  grassland: { material: 'lush_grass', color: '#5fa64b', walkable: true, movementCost: 1 },
  forest: { material: 'forest_floor', color: '#2f7137', walkable: true, movementCost: 1.35 },
  dense_forest: { material: 'dark_humus', color: '#1f4e2d', walkable: true, movementCost: 1.8 },
  savanna: { material: 'dry_grass', color: '#b3a24c', walkable: true, movementCost: 1.05 },
  desert: { material: 'hot_sand', color: '#d7a94f', walkable: true, movementCost: 1.25 },
  hills: { material: 'stony_grass', color: '#827d55', walkable: true, movementCost: 1.6 },
  mountain: { material: 'grey_rock', color: '#777b82', walkable: true, movementCost: 2.2 },
  snow: { material: 'snow', color: '#d9e6eb', walkable: true, movementCost: 1.9 },
  swamp: { material: 'wet_mud', color: '#42694a', walkable: true, movementCost: 2 }
});

export function sampleClimate(wx, wy) {
  const elevation = fbm(wx, wy, 10) + fbm(wx, wy, 99) * 0.35 - 0.12;
  const moisture = fbm(wx + 9000, wy - 4000, 20);
  const heat = fbm(wx - 3000, wy + 7000, 30) - Math.abs(wy) / 9000;
  return { elevation, moisture, heat };
}

export function classifyBiome(wx, wy) {
  const climate = sampleClimate(wx, wy);
  const { elevation, moisture, heat } = climate;
  let id;
  if (elevation < 0.30) id = 'ocean';
  else if (elevation < 0.35) id = 'beach';
  else if (elevation > 0.77) id = heat < 0.35 ? 'snow' : 'mountain';
  else if (elevation > 0.67) id = 'hills';
  else if (moisture > 0.76 && heat > 0.35) id = 'swamp';
  else if (moisture > 0.68) id = heat > 0.52 ? 'dense_forest' : 'forest';
  else if (moisture < 0.28 && heat > 0.50) id = 'desert';
  else if (moisture < 0.40) id = 'savanna';
  else id = 'grassland';
  return { id, definition: BIOMES[id], climate };
}

import { LAYERS } from '../core/constants.js';

export function createTileStack({ wx, wy, biomeSample }) {
  const { id, definition, climate } = biomeSample;
  return {
    wx,
    wy,
    layers: {
      [LAYERS.bedrock]: { kind: 'bedrock', material: climate.elevation > 0.67 ? 'granite' : 'sedimentary' },
      [LAYERS.substrate]: { kind: 'substrate', moisture: climate.moisture, heat: climate.heat },
      [LAYERS.terrain]: { kind: 'terrain', biome: id, material: definition.material, walkable: definition.walkable, movementCost: definition.movementCost },
      [LAYERS.surface]: { kind: 'surface', detail: chooseSurfaceDetail(id, climate) },
      [LAYERS.objects]: { kind: 'objects', items: [] },
      [LAYERS.structures]: { kind: 'structures', items: [] },
      [LAYERS.entities]: { kind: 'entities', items: [] },
      [LAYERS.lighting]: { kind: 'lighting', ambient: 1, local: 0 }
    },
    climate,
    biome: id,
    material: definition.material,
    walkable: definition.walkable,
    movementCost: definition.movementCost
  };
}

function chooseSurfaceDetail(biome, climate) {
  if (biome === 'ocean') return climate.elevation < 0.24 ? 'deep_water' : 'shallow_water';
  if (biome === 'beach') return climate.moisture > 0.5 ? 'wet_sand' : 'dry_sand';
  if (biome === 'forest' || biome === 'dense_forest') return 'leaf_litter';
  if (biome === 'mountain' || biome === 'hills') return 'stone_scatter';
  if (biome === 'swamp') return 'mud_pools';
  if (biome === 'snow') return 'snow_drift';
  return 'ground_cover';
}

export function addObjectToTile(tile, object) {
  tile.layers[LAYERS.objects].items.push(object);
}

export function projectTileForRender(tile, biomeDefinition) {
  return {
    color: biomeDefinition.color,
    elevation: tile.climate.elevation,
    biome: tile.biome,
    material: tile.material,
    surface: tile.layers[LAYERS.surface].detail,
    walkable: tile.walkable
  };
}

import { WORLD } from '../core/constants.js';

export function floorDiv(value, divisor = WORLD.chunkSize) {
  return Math.floor(value / divisor);
}

export function chunkKey(cx, cy) {
  return `${cx},${cy}`;
}

export function worldToChunk(wx, wy) {
  const cx = floorDiv(wx, WORLD.chunkSize);
  const cy = floorDiv(wy, WORLD.chunkSize);
  return { cx, cy, lx: wx - cx * WORLD.chunkSize, ly: wy - cy * WORLD.chunkSize };
}

export class ChunkStore {
  constructor(compiler) {
    this.compiler = compiler;
    this.chunks = new Map();
  }

  get(cx, cy) {
    const key = chunkKey(cx, cy);
    if (!this.chunks.has(key)) this.chunks.set(key, this.compiler.compile(cx, cy));
    return this.chunks.get(key);
  }

  streamAround(wx, wy) {
    const pcx = floorDiv(wx, WORLD.chunkSize);
    const pcy = floorDiv(wy, WORLD.chunkSize);
    for (let cy = pcy - WORLD.loadRadius; cy <= pcy + WORLD.loadRadius; cy++) {
      for (let cx = pcx - WORLD.loadRadius; cx <= pcx + WORLD.loadRadius; cx++) this.get(cx, cy);
    }
    const maxDistance = WORLD.loadRadius + WORLD.unloadPadding;
    for (const [key, chunk] of this.chunks) {
      if (Math.abs(chunk.cx - pcx) > maxDistance || Math.abs(chunk.cy - pcy) > maxDistance) this.chunks.delete(key);
    }
  }

  tileAt(wx, wy) {
    const { cx, cy, lx, ly } = worldToChunk(Math.floor(wx), Math.floor(wy));
    return this.get(cx, cy).tiles[ly * WORLD.chunkSize + lx];
  }
}

import { rand2 } from '../core/random.js';

const RULES = Object.freeze({
  forest: [{ kind: 'tree', threshold: 0.955 }, { kind: 'shrub', threshold: 0.987 }],
  dense_forest: [{ kind: 'tree', threshold: 0.91 }, { kind: 'fallen_log', threshold: 0.985 }],
  grassland: [{ kind: 'flower', threshold: 0.982 }, { kind: 'grass_tuft', threshold: 0.955 }],
  beach: [{ kind: 'shell', threshold: 0.988 }, { kind: 'driftwood', threshold: 0.994 }],
  hills: [{ kind: 'rock', threshold: 0.965 }],
  mountain: [{ kind: 'rock', threshold: 0.94 }],
  swamp: [{ kind: 'reed', threshold: 0.965 }, { kind: 'bog_log', threshold: 0.992 }],
  savanna: [{ kind: 'dry_shrub', threshold: 0.97 }],
  desert: [{ kind: 'cactus', threshold: 0.992 }],
  snow: [{ kind: 'ice_rock', threshold: 0.985 }]
});

export function placeObjectsForTile(tile) {
  const rules = RULES[tile.biome] || [];
  const value = rand2(tile.wx, tile.wy, 777);
  const placed = [];
  for (const rule of rules) {
    if (value > rule.threshold) placed.push({ kind: rule.kind, wx: tile.wx, wy: tile.wy, layer: 'objects' });
  }
  return placed;
}

import { WORLD } from '../core/constants.js';
import { BIOMES, classifyBiome } from './biomes.js';
import { createTileStack, addObjectToTile, projectTileForRender } from './tile-stack.js';
import { placeObjectsForTile } from './object-placement.js';

export class ChunkCompiler {
  compile(cx, cy) {
    const tiles = new Array(WORLD.chunkSize * WORLD.chunkSize);
    const renderTiles = new Array(WORLD.chunkSize * WORLD.chunkSize);
    const objects = [];

    for (let y = 0; y < WORLD.chunkSize; y++) {
      for (let x = 0; x < WORLD.chunkSize; x++) {
        const wx = cx * WORLD.chunkSize + x;
        const wy = cy * WORLD.chunkSize + y;
        const tile = createTileStack({ wx, wy, biomeSample: classifyBiome(wx, wy) });
        const placed = placeObjectsForTile(tile);
        for (const object of placed) {
          addObjectToTile(tile, object);
          objects.push({ ...object, x, y });
        }
        const index = y * WORLD.chunkSize + x;
        tiles[index] = tile;
        renderTiles[index] = projectTileForRender(tile, BIOMES[tile.biome]);
      }
    }

    return { cx, cy, tiles, renderTiles, objects };
  }
}

export class InputState {
  constructor(target = window) {
    this.keys = new Set();
    target.addEventListener('keydown', event => this.keys.add(event.key.toLowerCase()));
    target.addEventListener('keyup', event => this.keys.delete(event.key.toLowerCase()));
  }

  axis() {
    let x = 0;
    let y = 0;
    if (this.keys.has('w') || this.keys.has('arrowup')) y--;
    if (this.keys.has('s') || this.keys.has('arrowdown')) y++;
    if (this.keys.has('a') || this.keys.has('arrowleft')) x--;
    if (this.keys.has('d') || this.keys.has('arrowright')) x++;
    if (x || y) {
      const magnitude = Math.hypot(x, y);
      x /= magnitude;
      y /= magnitude;
    }
    return { x, y };
  }
}

export class Player {
  constructor() {
    this.x = 0;
    this.y = 0;
    this.speed = 9;
  }

  update(input, dt) {
    const axis = input.axis();
    this.x += axis.x * this.speed * dt;
    this.y += axis.y * this.speed * dt;
  }
}

import { WORLD } from '../core/constants.js';
import { floorDiv } from '../world/chunk.js';

export class CanvasRenderer {
  constructor(canvas, statsElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.statsElement = statsElement;
    window.addEventListener('resize', () => this.resize());
    this.resize();
  }

  resize() {
    this.canvas.width = Math.floor(window.innerWidth * window.devicePixelRatio);
    this.canvas.height = Math.floor(window.innerHeight * window.devicePixelRatio);
    this.ctx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);
  }

  draw(chunkStore, player) {
    const ctx = this.ctx;
    const w = window.innerWidth;
    const h = window.innerHeight;
    ctx.fillStyle = '#071019';
    ctx.fillRect(0, 0, w, h);

    const camX = player.x * WORLD.tileSize - w / 2;
    const camY = player.y * WORLD.tileSize - h / 2;
    const minTX = Math.floor(camX / WORLD.tileSize) - 1;
    const minTY = Math.floor(camY / WORLD.tileSize) - 1;
    const maxTX = Math.ceil((camX + w) / WORLD.tileSize) + 1;
    const maxTY = Math.ceil((camY + h) / WORLD.tileSize) + 1;

    for (let ty = minTY; ty <= maxTY; ty++) {
      for (let tx = minTX; tx <= maxTX; tx++) {
        const cx = floorDiv(tx, WORLD.chunkSize);
        const cy = floorDiv(ty, WORLD.chunkSize);
        const lx = tx - cx * WORLD.chunkSize;
        const ly = ty - cy * WORLD.chunkSize;
        const renderTile = chunkStore.get(cx, cy).renderTiles[ly * WORLD.chunkSize + lx];
        ctx.fillStyle = shade(renderTile.color, (renderTile.elevation - 0.5) * 0.28);
        ctx.fillRect(Math.floor(tx * WORLD.tileSize - camX), Math.floor(ty * WORLD.tileSize - camY), WORLD.tileSize, WORLD.tileSize);
      }
    }

    this.drawObjects(chunkStore, camX, camY, w, h);
    this.drawPlayer(w, h);
  }

  drawObjects(chunkStore, camX, camY, w, h) {
    for (const chunk of chunkStore.chunks.values()) {
      for (const object of chunk.objects) {
        const sx = (chunk.cx * WORLD.chunkSize + object.x) * WORLD.tileSize - camX;
        const sy = (chunk.cy * WORLD.chunkSize + object.y) * WORLD.tileSize - camY;
        if (sx < -20 || sy < -20 || sx > w + 20 || sy > h + 20) continue;
        drawObject(this.ctx, object.kind, sx, sy);
      }
    }
  }

  drawPlayer(w, h) {
    const ctx = this.ctx;
    ctx.fillStyle = '#f6f1d0';
    ctx.beginPath();
    ctx.arc(w / 2, h / 2, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#1b1b1b';
    ctx.stroke();
  }

  hud(chunkStore, player) {
    const tile = chunkStore.tileAt(player.x, player.y);
    this.statsElement.innerHTML = `WASD / arrows to move<br>seed ${WORLD.seed} · chunks ${chunkStore.chunks.size}<br>tile ${Math.floor(player.x)}, ${Math.floor(player.y)} · chunk ${floorDiv(player.x)}, ${floorDiv(player.y)}<br>biome ${tile.biome} · material ${tile.material}<br>surface ${tile.layers[3].detail}<br>elev ${tile.climate.elevation.toFixed(2)} moist ${tile.climate.moisture.toFixed(2)} heat ${tile.climate.heat.toFixed(2)}`;
  }
}

function drawObject(ctx, kind, sx, sy) {
  if (kind === 'tree') {
    ctx.fillStyle = '#12391f';
    ctx.beginPath();
    ctx.arc(sx + 8, sy + 8, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#6b4928';
    ctx.fillRect(sx + 6, sy + 8, 4, 7);
  } else if (kind.includes('rock')) {
    ctx.fillStyle = '#555a5f';
    ctx.fillRect(sx + 4, sy + 5, 9, 8);
  } else if (kind === 'flower') {
    ctx.fillStyle = '#ffd6f2';
    ctx.fillRect(sx + 7, sy + 7, 3, 3);
  } else if (kind.includes('shrub') || kind === 'reed' || kind === 'grass_tuft') {
    ctx.fillStyle = '#244f27';
    ctx.fillRect(sx + 5, sy + 6, 7, 7);
  } else {
    ctx.fillStyle = '#7b5b35';
    ctx.fillRect(sx + 5, sy + 6, 8, 5);
  }
}

function shade(hex, amount) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255;
  let g = (n >> 8) & 255;
  let b = n & 255;
  r = Math.max(0, Math.min(255, r + amount * 255));
  g = Math.max(0, Math.min(255, g + amount * 255));
  b = Math.max(0, Math.min(255, b + amount * 255));
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}

